static void add(void) {
  int i, j, k, m;

  const int i_end = grid_points[0] - 1;
  const int j_end = grid_points[1] - 1;
  const int k_end = grid_points[2] - 1;

  for (i = 1; i < i_end; i++) {
    for (j = 1; j < j_end; j++) {
      for (k = 1; k < k_end; k++) {
        double *up = &u[i][j][k][0];
        double *rp = &rhs[i][j][k][0];
#if defined(__riscv_vector)
        size_t remaining = 5;
        size_t offset = 0;
        while (remaining > 0) {
          size_t vl = __riscv_vsetvl_e64m1(remaining);
          vfloat64m1_t vu = __riscv_vle64_v_f64m1(up + offset, vl);
          vfloat64m1_t vr = __riscv_vle64_v_f64m1(rp + offset, vl);
          vu = __riscv_vfadd_vv_f64m1(vu, vr, vl);
          __riscv_vse64_v_f64m1(up + offset, vu, vl);
          offset += vl;
          remaining -= vl;
        }
#else
        for (m = 0; m < 5; m++) {
          up[m] = up[m] + rp[m];
        }
#endif
      }
    }
  }
}

static void exact_rhs(void) {
  double dtemp[5], xi, eta, zeta, dtpp;
  int m, i, j, k, ip1, im1, jp1, jm1, km1, kp1;
  const int gp0 = grid_points[0];
  const int gp1 = grid_points[1];
  const int gp2 = grid_points[2];

#if defined(__riscv_vector)
  #include <riscv_vector.h>
#endif

  for (i = 0; i < gp0; i++) {
    for (j = 0; j < gp1; j++) {
      for (k = 0; k < gp2; k++) {
#if defined(__riscv_vector)
        double *f = forcing[i][j][k];
        size_t vl = __riscv_vsetvl_e64m1(4);
        vfloat64m1_t vz = __riscv_vfmv_v_f_f64m1(0.0, vl);
        __riscv_vse64_v_f64m1(f, vz, vl);
        f[4] = 0.0;
#else
        for (m = 0; m < 5; m++) {
          forcing[i][j][k][m] = 0.0;
        }
#endif
      }
    }
  }

  for (j = 1; j < gp1-1; j++) {
    eta = (double)j * dnym1;

    for (k = 1; k < gp2-1; k++) {
      zeta = (double)k * dnzm1;

      for (i = 0; i < gp0; i++) {
        xi = (double)i * dnxm1;

        exact_solution(xi, eta, zeta, dtemp);
        for (m = 0; m < 5; m++) {
          ue[i][m] = dtemp[m];
        }

        dtpp = 1.0 / dtemp[0];

        for (m = 1; m <= 4; m++) {
          buf[i][m] = dtpp * dtemp[m];
        }

        cuf[i] = buf[i][1] * buf[i][1];
        buf[i][0] = cuf[i] + buf[i][2] * buf[i][2] +
                    buf[i][3] * buf[i][3];
        q[i] = 0.5 * (buf[i][1] * ue[i][1] + buf[i][2] * ue[i][2] +
                      buf[i][3] * ue[i][3]);
      }

      for (i = 1; i < gp0-1; i++) {
        im1 = i - 1;
        ip1 = i + 1;

        forcing[i][j][k][0] = forcing[i][j][k][0] -
          tx2 * (ue[ip1][1] - ue[im1][1]) +
          dx1tx1 * (ue[ip1][0] - 2.0 * ue[i][0] + ue[im1][0]);

        forcing[i][j][k][1] = forcing[i][j][k][1] -
          tx2 * ((ue[ip1][1] * buf[ip1][1] + c2 * (ue[ip1][4] - q[ip1])) -
                 (ue[im1][1] * buf[im1][1] + c2 * (ue[im1][4] - q[im1]))) +
          xxcon1 * (buf[ip1][1] - 2.0 * buf[i][1] + buf[im1][1]) +
          dx2tx1 * (ue[ip1][1] - 2.0 * ue[i][1] + ue[im1][1]);

        forcing[i][j][k][2] = forcing[i][j][k][2] -
          tx2 * (ue[ip1][2] * buf[ip1][1] - ue[im1][2] * buf[im1][1]) +
          xxcon2 * (buf[ip1][2] - 2.0 * buf[i][2] + buf[im1][2]) +
          dx3tx1 * (ue[ip1][2] - 2.0 * ue[i][2] + ue[im1][2]);

        forcing[i][j][k][3] = forcing[i][j][k][3] -
          tx2 * (ue[ip1][3] * buf[ip1][1] - ue[im1][3] * buf[im1][1]) +
          xxcon2 * (buf[ip1][3] - 2.0 * buf[i][3] + buf[im1][3]) +
          dx4tx1 * (ue[ip1][3] - 2.0 * ue[i][3] + ue[im1][3]);

        forcing[i][j][k][4] = forcing[i][j][k][4] -
          tx2 * (buf[ip1][1] * (c1 * ue[ip1][4] - c2 * q[ip1]) -
                 buf[im1][1] * (c1 * ue[im1][4] - c2 * q[im1])) +
          0.5 * xxcon3 * (buf[ip1][0] - 2.0 * buf[i][0] + buf[im1][0]) +
          xxcon4 * (cuf[ip1] - 2.0 * cuf[i] + cuf[im1]) +
          xxcon5 * (buf[ip1][4] - 2.0 * buf[i][4] + buf[im1][4]) +
          dx5tx1 * (ue[ip1][4] - 2.0 * ue[i][4] + ue[im1][4]);
      }

      for (m = 0; m < 5; m++) {
        i = 1;
        forcing[i][j][k][m] = forcing[i][j][k][m] - dssp *
