        i = 2;
        forcing[i][j][k][m] = forcing[i][j][k][m] - dssp *
          (-4.0 * ue[i-1][m] + 6.0 * ue[i][m] -
           4.0 * ue[i+1][m] + ue[i+2][m]);
      }

      for (m = 0; m < 5; m++) {
        for (i = 3; i <= gp0-4; i++) {
