            (ue[i-2][m] - 4.0 * ue[i-1][m] +
             6.0 * ue[i][m] - 4.0 * ue[i+1][m] + ue[i+2][m]);
        }
      }

      for (m = 0; m < 5; m++) {
        i = gp0-3;
        forcing[i][j][k][m] = forcing[i][j][k][m] - dssp *
          (ue[i-2][m] - 4.0 * ue[i-1][m] +
