        i = gp0-2;
        forcing[i][j][k][m] = forcing[i][j][k][m] - dssp *
          (ue[i-2][m] - 4.0 * ue[i-1][m] + 5.0 * ue[i][m]);
      }
    }
  }

  for (i = 1; i < gp0-1; i++) {
    xi = (double)i * dnxm1;

    for (k = 1; k < gp2-1; k++) {
      zeta = (double)k * dnzm1;

      for (j = 0; j < gp1; j++) {
        eta = (double)j * dnym1;

        exact_solution(xi, eta, zeta, dtemp);
        for (m = 0; m < 5; m++) {
