          yycon5 * (buf[jp1][4] - 2.0 * buf[j][4] + buf[jm1][4]) +
          dy5ty1 * (ue[jp1][4] - 2.0 * ue[j][4] + ue[jm1][4]);
      }

      for (m = 0; m < 5; m++) {
        j = 1;
        forcing[i][j][k][m] = forcing[i][j][k][m] - dssp *
          (5.0 * ue[j][m] - 4.0 * ue[j+1][m] + ue[j+2][m]);
        j = 2;
        forcing[i][j][k][m] = forcing[i][j][k][m] - dssp *
