           4.0 * ue[j+1][m] + ue[j+2][m]);
      }

      for (m = 0; m < 5; m++) {
        for (j = 3; j <= gp1-4; j++) {
          forcing[i][j][k][m] = forcing[i][j][k][m] - dssp *
            (ue[j-2][m] - 4.0 * ue[j-1][m] +
             6.0 * ue[j][m] - 4.0 * ue[j+1][m] + ue[j+2][m]);
        }
      }

      for (m = 0; m < 5; m++) {
        j = gp1-3;
        forcing[i][j][k][m] = forcing[i][j][k][m] - dssp *
          (ue[j-2][m] - 4.0 * ue[j-1][m] +
           6.0 * ue[j][m] - 4.0 * ue[j+1][m]);
        j = gp1-2;
        forcing[i][j][k][m] = forcing[i][j][k][m] - dssp *
