static void initialize(void) {

{
  int i, j, k, ix, iy, iz;
  const int gp0 = grid_points[0];
  const int gp1 = grid_points[1];
  const int gp2 = grid_points[2];
  double xi, eta, zeta, Pface[2][3][5], temp[5];

  for (i = 0; i < IMAX; i++) {
    for (j = 0; j < IMAX; j++) {
      for (k = 0; k < IMAX; k++) {
        u[i][j][k][0] = 1.0;
        u[i][j][k][1] = 1.0;
        u[i][j][k][2] = 1.0;
        u[i][j][k][3] = 1.0;
        u[i][j][k][4] = 1.0;
      }
    }
  }

  for (i = 0; i < gp0; i++) {
    xi = (double)i * dnxm1;

    for (j = 0; j < gp1; j++) {
      eta = (double)j * dnym1;

      for (k = 0; k < gp2; k++) {
        zeta = (double)k * dnzm1;

        for (ix = 0; ix < 2; ix++) {
          exact_solution((double)ix, eta, zeta, &(Pface[ix][0][0]));
        }

        for (iy = 0; iy < 2; iy++) {
          exact_solution(xi, (double)iy, zeta, &(Pface[iy][1][0]));
        }

        for (iz = 0; iz < 2; iz++) {
          exact_solution(xi, eta, (double)iz, &(Pface[iz][2][0]));
        }

        {
          size_t vl = __riscv_vsetvl_e64m1(5);
          vfloat64m1_t v_pface_x0 = __riscv_vle64_v_f64m1(&(Pface[0][0][0]), vl);
          vfloat64m1_t v_pface_x1 = __riscv_vle64_v_f64m1(&(Pface[1][0][0]), vl);
          vfloat64m1_t v_pface_y0 = __riscv_vle64_v_f64m1(&(Pface[0][1][0]), vl);
          vfloat64m1_t v_pface_y1 = __riscv_vle64_v_f64m1(&(Pface[1][1][0]), vl);
          vfloat64m1_t v_pface_z0 = __riscv_vle64_v_f64m1(&(Pface[0][2][0]), vl);
          vfloat64m1_t v_pface_z1 = __riscv_vle64_v_f64m1(&(Pface[1][2][0]), vl);

          vfloat64m1_t v_xi = __riscv_vfmv_v_f_f64m1(xi, vl);
          vfloat64m1_t v_eta = __riscv_vfmv_v_f_f64m1(eta, vl);
          vfloat64m1_t v_zeta = __riscv_vfmv_v_f_f64m1(zeta, vl);
          vfloat64m1_t v_one = __riscv_vfmv_v_f_f64m1(1.0, vl);

          vfloat64m1_t v_Pxi = __riscv_vfadd_vv_f64m1(
              __riscv_vfmul_vv_f64m1(v_xi, v_pface_x1, vl),
              __riscv_vfmul_vv_f64m1(__riscv_vfsub_vv_f64m1(v_one, v_xi, vl), v_pface_x0, vl),
              vl);

          vfloat64m1_t v_Peta = __riscv_vfadd_vv_f64m1(
              __riscv_vfmul_vv_f64m1(v_eta, v_pface_y1, vl),
              __riscv_vfmul_vv_f64m1(__riscv_vfsub_vv_f64m1(v_one, v_eta, vl), v_pface_y0, vl),
              vl);

          vfloat64m1_t v_Pzeta = __riscv_vfadd_vv_f64m1(
              __riscv_vfmul_vv_f64m1(v_zeta, v_pface_z1, vl),
              __riscv_vfmul_vv_f64m1(__riscv_vfsub_vv_f64m1(v_one, v_zeta, vl), v_pface_z0, vl),
              vl);

          vfloat64m1_t v_res = __riscv_vfadd_vv_f64m1(
              __riscv_vfsub_vv_f64m1(
                  __riscv_vfadd_vv_f64m1(
                      __riscv_vfadd_vv_f64m1(v_Pxi, v_Peta, vl),
                      v_Pzeta, vl),
                  __riscv_vfadd_vv_f64m1(
                      __riscv_vfadd_vv_f64m1(
                          __riscv_vfmul_vv_f64m1(v_Pxi, v_Peta, vl),
                          __riscv_vfmul_vv_f64m1(v_Pxi, v_Pzeta, vl), vl),
                      __riscv_vfmul_vv_f64m1(v_Peta, v_Pzeta, vl), vl),
