static void lhsx(void) {

  int i, j, k;

  const double tdtx1 = dt * tx1;
  const double tdtx2 = dt * tx2;
  const double two_tdtx1 = 2.0 * tdtx1;

  const double aa_dx1 = tdtx1 * dx1;
  const double aa_dx2 = tdtx1 * dx2;
  const double aa_dx3 = tdtx1 * dx3;
  const double aa_dx4 = tdtx1 * dx4;
  const double aa_dx5 = tdtx1 * dx5;

  const double bb_dx1 = two_tdtx1 * dx1;
  const double bb_dx2 = two_tdtx1 * dx2;
  const double bb_dx3 = two_tdtx1 * dx3;
  const double bb_dx4 = two_tdtx1 * dx4;
  const double bb_dx5 = two_tdtx1 * dx5;

  const double n41 = con43 * c3c4 - c1345;
  const double n42 = c3c4 - c1345;
  const double half_c2 = 0.5 * c2;
  const double two_minus_c2 = 2.0 - c2;

  for (j = 1; j < grid_points[1]-1; j++) {
    for (k = 1; k < grid_points[2]-1; k++) {

      for (i = 0; i < grid_points[0]; i++) {
        double *uu = &u[i][j][k][0];

        double u0 = uu[0];
        double u1 = uu[1];
        double u2 = uu[2];
        double u3 = uu[3];
        double u4 = uu[4];

	tmp1 = 1.0 / u0;
	tmp2 = tmp1 * tmp1;
	tmp3 = tmp1 * tmp2;

        {
          double s123 = u1*u1 + u2*u2 + u3*u3;
          double u1t1 = u1 * tmp1;
          double u2t1 = u2 * tmp1;
          double u3t1 = u3 * tmp1;
          double u4t1 = u4 * tmp1;
          double c2s_tmp2 = c2 * s123 * tmp2;

          double (*fj)[5] = fjac[i][j][k];
          double (*nj)[5] = njac[i][j][k];

	  fj[0][0] = 0.0;
	  fj[0][1] = 1.0;
	  fj[0][2] = 0.0;
	  fj[0][3] = 0.0;
	  fj[0][4] = 0.0;

	  fj[1][0] = -(u1 * tmp2 * u1) + half_c2 * s123 * tmp2;
	  fj[1][1] = two_minus_c2 * u1t1;
	  fj[1][2] = - c2 * u2t1;
	  fj[1][3] = - c2 * u3t1;
	  fj[1][4] = c2;

	  fj[2][0] = -(u1 * u2) * tmp2;
	  fj[2][1] = u2t1;
	  fj[2][2] = u1t1;
	  fj[2][3] = 0.0;
	  fj[2][4] = 0.0;

	  fj[3][0] = -(u1 * u3) * tmp2;
	  fj[3][1] = u3t1;
	  fj[3][2] = 0.0;
	  fj[3][3] = u1t1;
	  fj[3][4] = 0.0;

	  fj[4][0] = ( c2s_tmp2 - c1 * u4t1 ) * u1t1;
	  fj[4][1] = c1 * u4t1 - half_c2 * (3.0*u1*u1 + u2*u2 + u3*u3) * tmp2;
	  fj[4][2] = - c2 * (u2 * u1) * tmp2;
	  fj[4][3] = - c2 * (u3 * u1) * tmp2;
	  fj[4][4] = c1 * u1t1;

	  nj[0][0] = 0.0;
	  nj[0][1] = 0.0;
	  nj[0][2] = 0.0;
	  nj[0][3] = 0.0;
	  nj[0][4] = 0.0;

	  nj[1][0] = - con43 * c3c4 * tmp2 * u1;
	  nj[1][1] =   con43 * c3c4 * tmp1;
	  nj[1][2] =   0.0;
	  nj[1][3] =   0.0;
	  nj[1][4] =   0.0;

	  nj[2][0] = - c3c4 * tmp2 * u2;
	  nj[2][1] =   0.0;
	  nj[2][2] =   c3c4 * tmp1;
	  nj[2][3] =   0.0;
	  nj[2][4] =   0.0;

	  nj[3][0] = - c3c4 * tmp2 * u3;
	  nj[3][1] =   0.0;
	  nj[3][2] =   0.0;
	  nj[3][3] =   c3c4 * tmp1;
	  nj[3][4] =   0.0;

	  nj[4][0] = - n41 * tmp3 * (u1*u1)
	    - n42 * tmp3 * (u2*u2)
	    - n42 * tmp3 * (u3*u3)
	    - c1345 * tmp2 * u4;

	  nj[4][1] = n41 * tmp2 * u1;
	  nj[4][2] = n42 * tmp2 * u2;
	  nj[4][3] = n42 * tmp2 * u3;
	  nj[4][4] = c1345 * tmp1;
        }
      }

      for (i = 1; i < grid_points[0]-1; i++) {
        double (*fjm)[5] = fjac[i-1][j][k];
        double (*njm)[5] = njac[i-1][j][k];
        double (*nj0)[5] = njac[i][j][k];
        double (*fjp)[5] = fjac[i+1][j][k];
        double (*njp)[5] = njac[i+1][j][k];

        double (*lA)[5] = lhs[i][j][k][AA];
        double (*lB)[5] = lhs[i][j][k][BB];
        double (*lC)[5] = lhs[i][j][k][CC];

#if defined(__riscv_vector) && defined(__GNUC__)
        {
          int r;
          for (r = 0; r < 5; r++) {
            size_t vl = 5;
            vfloat64m1_t vfjm = __riscv_vle64_v_f64m1(&fjm[r][0], vl);
            vfloat64m1_t vnjm = __riscv_vle64_v_f64m1(&njm[r][0], vl);
            vfloat64m1_t vnj0 = __riscv_vle64_v_f64m1(&nj0[r][0], vl);
            vfloat64m1_t vfjp = __riscv_vle64_v_f64m1(&fjp[r][0], vl);
            vfloat64m1_t vnjp = __riscv_vle64_v_f64m1(&njp[r][0], vl);

            vfloat64m1_t va = __riscv_vfmul_vf_f64m1(vfjm, -tdtx2, vl);
            va = __riscv_vfmacc_vf_f64m1(va, -tdtx1, vnjm, vl);

            vfloat64m1_t vb = __riscv_vfmul_vf_f64m1(vnj0, two_tdtx1, vl);
            vb = __riscv_vfadd_vf_f64m1(vb, 1.0, vl);

            vfloat64m1_t vc = __riscv_vfmul_vf_f64m1(vfjp,  tdtx2, vl);
            vc = __riscv_vfmacc_vf_f64m1(vc, -tdtx1, vnjp, vl);

            __riscv_vse64_v_f64m1(&lA[r][0], va, vl);
            __riscv_vse64_v_f64m1(&lB[r][0], vb, vl);
            __riscv_vse64_v_f64m1(&lC[r][0], vc, vl);
          }
        }
#else
        {
          int r, c;
          for (r = 0; r < 5; r++) {
            for (c = 0; c < 5; c++) {
              lA[r][c] = -tdtx2 * fjm[r][c] - tdtx1 * njm[r][c];
              lB[r][c] =  two_tdtx1 * nj0[r][c];
              lC[r][c] =  tdtx2 * fjp[r][c] - tdtx1 * njp[r][c];
            }
            lB[r][r] += 1.0;
          }
        }
#endif

        lA[0][0] -= aa_dx1;
        lA[1][1] -= aa_dx2;
        lA[2][2] -= aa_dx3;
        lA[3][3] -= aa_dx4;
        lA[4][4] -= aa_dx5;

        lB[0][0] += bb_dx1;
        lB[1][1] += bb_dx2;
        lB[2][2] += bb_dx3;
        lB[3][3] += bb_dx4;
        lB[4][4] += bb_dx5;

        lC[0][0] -= aa_dx1;
        lC[1][1] -= aa_dx2;
        lC[2][2] -= aa_dx3;
        lC[3][3] -= aa_dx4;
        lC[4][4] -= aa_dx5;
      }
    }
  }
}

