static inline int rvv_prod3_i32(const int *gp) {
  size_t vl = __riscv_vsetvl_e32m1(3);
  vint32m1_t vgp = __riscv_vle32_v_i32m1(gp, vl);
  vint32m1_t vone = __riscv_vmv_v_x_i32m1(1, vl);
  vint32m1_t vmul = __riscv_vmul_vv_i32m1(vgp, vone, vl);
  int vals[3];
  __riscv_vse32_v_i32m1(vals, vmul, vl);
  return vals[0] * vals[1] * vals[2];
}

static inline double rvv_avg3_f64(const int *gp) {
  double vals[3];
  vals[0] = (double)gp[0];
  vals[1] = (double)gp[1];
  vals[2] = (double)gp[2];
  size_t vl = __riscv_vsetvl_e64m1(3);
  vfloat64m1_t v = __riscv_vle64_v_f64m1(vals, vl);
  double sum = __riscv_vfmv_f_s_f64m1_f64(__riscv_vfredusum_vs_f64m1_f64m1(
      v, __riscv_vfmv_v_f_f64m1(0.0, 1), vl));
  return sum * (1.0 / 3.0);
}
#endif

